export function failStep(run, status, reason) {
  if (status !== "partial" && status !== "failed") {
    throw new Error(`Invalid fail status: "${status}". Use "partial" or "failed"`);
  }

  const active = run.steps.find((s) => s.status === "active");
  if (!active) {
    throw new Error("No active step to fail");
  }

  active.status = status;
  active.note = reason;
  active.completedAt = new Date().toISOString();

  // Mission status follows the worst step
  run.status = status;
  run.completedAt = new Date().toISOString();

  return active;
}

export function failStep(run, status, reason) {
  if (status !== "partial" && status !== "failed") {
    throw new Error(`Invalid fail status: "${status}". Use "partial" or "failed"`);
  }

  const active = run.steps.find((s) => s.status === "active");
  if (!active) {
    throw new Error("No active step to fail");
  }

  active.status = status;
  active.note = reason;
  active.completedAt = new Date().toISOString();

  // Block all downstream pending steps (S2-F2)
  let foundActive = false;
  for (const step of run.steps) {
    if (step === active) { foundActive = true; continue; }
    if (foundActive && step.status === "pending") {
      step.status = "blocked";
      step.note = `Blocked: upstream ${active.role} ${status}`;
    }
  }

  // Mission status follows the worst step
  run.status = status;
  run.completedAt = new Date().toISOString();

  return active;
}

export function cheapestChain(graph, targetId) {
  if (!graph || !Array.isArray(graph.edges)) return null;
  const incoming = new Map();
  for (const e of graph.edges) {
    if (e.closure_implied) continue;
    if (!incoming.has(e.to)) incoming.set(e.to, []);
    incoming.get(e.to).push(e);
  }
  // Walk prerequisites back from the target (structural; the graph is a DAG).
  const chain = [];
  let verified = true, saved = 0, cur = targetId;
  const guard = new Set();
  while (incoming.has(cur) && !guard.has(cur)) {
    guard.add(cur);
    // pick the highest-witness incoming prerequisite
    const best = incoming.get(cur).slice().sort((a, b) => b.witness - a.witness)[0];
    chain.unshift(best.from);
    if (best.evidence === "confirmed" && best.outcome_delta) saved += best.outcome_delta.steps_saved_frac;
    else verified = false;
    cur = best.from;
  }
  return chain.length ? { chain, steps_saved_frac: verified ? Math.round(saved * 1e4) / 1e4 : null, verified } : null;
}

