    vals = sorted(fn([p[i] for i in s], [y[i] for i in s])
                  for s in ([rng.choice(idx) for _ in idx] for _ in range(n)))
    return [round(vals[int(0.025 * n)], 4), round(vals[int(0.975 * n)], 4)]


