/**
 * Structured error output. Matches shipcheck error shape:
 * code, message, hint, cause?, retryable?
 *
 * Usage errors print the human usage block on stderr. `--json` keeps the
 * machine blob; `--debug` dumps a stack.
 */
function handleError(err) {
  const isUserError = err.exitCode === 1;
  const code = isUserError ? "USER_ERROR" : "RUNTIME_ERROR";
  const exitCode = isUserError ? 1 : 2;
  const jsonMode = process.argv.includes("--json");

  if (process.argv.includes("--debug")) {
    console.error(err.stack || err);
    process.exit(exitCode);
  }

  if (jsonMode || !isUserError) {
    console.error(JSON.stringify({
      code,
      message: err.message,
      hint: err.hint || null,
      retryable: false,
    }));
    process.exit(exitCode);
  }

  const lines = usageLinesFor(command);
  if (lines) {
    console.error(`\nUsage:\n${lines}\n`);
  } else {
    printHelp(console.error);
  }
  console.error(`${code}: ${err.message}`);
  if (err.hint) console.error(err.hint);
  process.exit(exitCode);
}

/**
 * Structured error output. Matches shipcheck error shape:
 * code, message, hint, cause?, retryable?
 *
 * Post-verb `--help`/`-h` is intercepted before dispatch (printVerbHelp).
 * `roleos run` with no args prints usage from run-cmd and exits 1.
 * Thrown USER_ERROR stays a JSON blob so `--json` and existing parsers
 * keep a machine-readable stderr.
 */
function handleError(err) {
  const isUserError = err.exitCode === 1;
  const code = isUserError ? "USER_ERROR" : "RUNTIME_ERROR";
  const exitCode = isUserError ? 1 : 2;

  if (process.argv.includes("--debug")) {
    console.error(err.stack || err);
    process.exit(exitCode);
  }

  console.error(JSON.stringify({
    code,
    message: err.message,
    hint: err.hint || null,
    retryable: false,
  }));
  process.exit(exitCode);
}

def required_mbps(download_gb: float, download_minutes: float) -> float:
    """The download rate, in MB/s, that fetches `download_gb` in `download_minutes`."""
    return download_gb * 1000 / (download_minutes * 60)


def projected_minutes(download_gb: float, nbytes: int, seconds: float) -> float:
    """How long `download_gb` takes at the rate measured on the shard."""
    rate = nbytes / 1e6 / max(seconds, 1e-6)
    return download_gb * 1000 / max(rate, 1e-6) / 60


def probe_timeout(shard_bytes: int, need_mbps: float) -> float:
    """Seconds to wait for the shard: twice what the floor allows for it. A host that takes
    longer is refused without waiting for the whole shard."""
    return 2 * shard_bytes / 1e6 / need_mbps

